-- ---------------------------------------------------------------------------
-- 015_evidence.sql  (skipped if it is already recorded in schema_migrations)
-- ---------------------------------------------------------------------------
DO $apply13$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '015_evidence.sql') THEN
    EXECUTE $mig$
-- ---------------------------------------------------------------------------------------------------------
-- Phase 6: evidence (docs/integration/PHASE6_DESIGN.md).
--
--   evidence_requirement  what the request says must be shown, and WHICH registered principal may show it. Written with the request, never changed.
--   evidence_submission   a signed statement by that principal about one commit of the session. Written once, never changed.
--
-- The database refuses a submission that names an issuer the request did not name, a key that is not the issuer's, a commit the session
-- did not produce, a session that is not running, or a specification other than the one the request pinned. The application checks the
-- same things first and gives better messages; these are the backstop.
-- ---------------------------------------------------------------------------------------------------------

CREATE TABLE evidence_requirement (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  work_session_id UUID NOT NULL REFERENCES work_session (id) ON DELETE CASCADE,
  evidence_type TEXT NOT NULL CHECK (evidence_type ~ '^[a-z][a-z0-9_.-]{0,63}$'),
  is_required BOOLEAN NOT NULL DEFAULT true,
  issuer_principal_id UUID NOT NULL REFERENCES service_principal (id),   -- always a registered principal, never a free string
  tied_to_commit BOOLEAN NOT NULL DEFAULT true,
  specification_hash CHAR(64) CHECK (specification_hash IS NULL OR specification_hash ~ '^[0-9a-f]{64}$'),
  max_age_seconds INTEGER CHECK (max_age_seconds IS NULL OR max_age_seconds BETWEEN 60 AND 31536000),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_evidence_requirement UNIQUE (work_session_id, evidence_type)
);

-- Only with the request: the session is still waiting for approval, an automated one, and the issuer belongs to the same creator and may submit evidence.
CREATE FUNCTION evidence_requirement_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM work_session s
      JOIN project p ON p.id = s.project_id
      JOIN service_principal sp ON sp.id = NEW.issuer_principal_id
     WHERE s.id = NEW.work_session_id AND s.session_type = 'automated_work_session' AND s.status = 'requested' AND s.approved_at IS NULL
       AND sp.creator_id = p.creator_id AND 'evidence:submit' = ANY (sp.allowed_scopes)
  ) THEN
    RAISE EXCEPTION 'evidence_requirement: only with a pending request, naming a principal of the same owner that may submit evidence'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_evidence_requirement_guard BEFORE INSERT ON evidence_requirement
  FOR EACH ROW EXECUTE FUNCTION evidence_requirement_guard();

CREATE TABLE evidence_submission (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  work_session_id UUID NOT NULL REFERENCES work_session (id) ON DELETE CASCADE,
  evidence_type TEXT NOT NULL,
  issuer_principal_id UUID NOT NULL REFERENCES service_principal (id),
  signature_key_id UUID NOT NULL REFERENCES service_principal_key (id),
  subject_commit CHAR(40) NOT NULL CHECK (subject_commit ~ '^[0-9a-f]{40}$'),
  status TEXT NOT NULL CHECK (status IN ('pass', 'fail', 'inconclusive')),
  specification_hash CHAR(64) NOT NULL CHECK (specification_hash ~ '^[0-9a-f]{64}$'),
  evidence_hash CHAR(64) NOT NULL CHECK (evidence_hash ~ '^[0-9a-f]{64}$'),
  payload_sha256 CHAR(64) NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  issued_at TIMESTAMPTZ NOT NULL,
  signature_algorithm TEXT NOT NULL CHECK (signature_algorithm IN ('Ed25519', 'ES256')),
  signature_value TEXT NOT NULL CHECK (signature_value ~ '^[A-Za-z0-9_-]{86}$'),
  raw_payload JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(raw_payload) = 'object'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_evidence_once UNIQUE (work_session_id, evidence_type, subject_commit, evidence_hash)
);
CREATE INDEX idx_evidence_submission_session ON evidence_submission (work_session_id, evidence_type, issued_at DESC);

CREATE FUNCTION evidence_submission_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  req evidence_requirement%ROWTYPE;
  committed timestamptz;
BEGIN
  SELECT * INTO req FROM evidence_requirement
   WHERE work_session_id = NEW.work_session_id AND evidence_type = NEW.evidence_type AND issuer_principal_id = NEW.issuer_principal_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'evidence_submission: the session did not ask this principal for this kind of evidence' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM service_principal_key k WHERE k.id = NEW.signature_key_id AND k.principal_id = NEW.issuer_principal_id AND k.algorithm = NEW.signature_algorithm) THEN
    RAISE EXCEPTION 'evidence_submission: the signing key is not a key of the issuing principal' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM work_session s WHERE s.id = NEW.work_session_id AND s.session_type = 'automated_work_session' AND s.status IN ('active', 'awaiting_evidence')) THEN
    RAISE EXCEPTION 'evidence_submission: the session is not running' USING ERRCODE = 'check_violation';
  END IF;
  SELECT created_at INTO committed FROM session_commit WHERE work_session_id = NEW.work_session_id AND real_sha = NEW.subject_commit;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'evidence_submission: the commit is not one this session produced' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.issued_at < date_trunc('second', committed) THEN
    RAISE EXCEPTION 'evidence_submission: evidence cannot be issued before the commit existed' USING ERRCODE = 'check_violation';
  END IF;
  IF req.specification_hash IS NOT NULL AND req.specification_hash <> NEW.specification_hash THEN
    RAISE EXCEPTION 'evidence_submission: not the specification the request pinned' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_evidence_submission_guard BEFORE INSERT ON evidence_submission
  FOR EACH ROW EXECUTE FUNCTION evidence_submission_guard();

-- Records: written once (session_record_immutable() is from migration 014). roles.sql also revokes UPDATE and DELETE from the application's account.
CREATE TRIGGER trg_evidence_requirement_immutable BEFORE UPDATE OR DELETE ON evidence_requirement FOR EACH ROW EXECUTE FUNCTION session_record_immutable();
CREATE TRIGGER trg_evidence_submission_immutable BEFORE UPDATE OR DELETE ON evidence_submission FOR EACH ROW EXECUTE FUNCTION session_record_immutable();

$mig$;
    INSERT INTO schema_migrations (version) VALUES ('015_evidence.sql');
    RAISE NOTICE 'applied 015_evidence.sql';
  ELSE
    RAISE NOTICE 'skipped 015_evidence.sql (already applied)';
  END IF;
END
$apply13$;

-- ---------------------------------------------------------------------------
-- 016_contribution_attribution.sql  (skipped if it is already recorded in schema_migrations)
-- ---------------------------------------------------------------------------
DO $apply14$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '016_contribution_attribution.sql') THEN
    EXECUTE $mig$
-- ---------------------------------------------------------------------------------------------------------
-- Phase 7a: contribution attribution (docs/integration/PHASE7_DESIGN.md).
--
-- For every commit a session pushed (every session_commit), one record of who did what, with the roles kept apart:
--   author     the executor the session declared (and its principal): the only author a real commit can have
--   committer  always the gateway
--   sponsor    the creator who approved the session and answers for it
--   declared   what the pushed commit claimed as its author: kept as evidence, never trusted
--
-- The record is DERIVED BY THE DATABASE from the session when the commit is recorded (trigger on session_commit), so no code path
-- can write a different author, and it cannot be changed afterwards. A pushed commit can name a creator as its author, but the
-- attribution still says who really wrote it.
-- ---------------------------------------------------------------------------------------------------------

CREATE TABLE contribution_attribution (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  work_session_id UUID NOT NULL REFERENCES work_session (id) ON DELETE CASCADE,
  project_id UUID NOT NULL REFERENCES project (id),
  repository_id UUID NOT NULL REFERENCES repository (id),
  real_sha CHAR(40) NOT NULL CHECK (real_sha ~ '^[0-9a-f]{40}$'),
  view_sha CHAR(40) NOT NULL CHECK (view_sha ~ '^[0-9a-f]{40}$'),
  author_principal_id UUID NOT NULL REFERENCES service_principal (id),
  author_executor_type TEXT NOT NULL,
  author_executor_provider TEXT,
  author_executor_model TEXT,
  author_executor_external_id TEXT,
  author_executor_display_name TEXT,
  committer_kind TEXT NOT NULL DEFAULT 'gateway' CHECK (committer_kind = 'gateway'),
  sponsor_id UUID NOT NULL REFERENCES creator (id),
  declared_author TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_attribution_commit UNIQUE (work_session_id, real_sha)
);
CREATE INDEX idx_attribution_project ON contribution_attribution (project_id, created_at);

-- Backstop: whatever inserts a row, the author and sponsor must be those of the session.
CREATE FUNCTION contribution_attribution_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM work_session s
     WHERE s.id = NEW.work_session_id AND s.session_type = 'automated_work_session'
       AND s.requested_by_principal_id = NEW.author_principal_id AND s.sponsor_id = NEW.sponsor_id
       AND s.project_id = NEW.project_id AND s.repository_id = NEW.repository_id
       AND s.executor_type = NEW.author_executor_type
       AND s.executor_provider IS NOT DISTINCT FROM NEW.author_executor_provider AND s.executor_model IS NOT DISTINCT FROM NEW.author_executor_model
       AND s.executor_external_id IS NOT DISTINCT FROM NEW.author_executor_external_id AND s.executor_display_name IS NOT DISTINCT FROM NEW.author_executor_display_name
  ) THEN
    RAISE EXCEPTION 'contribution_attribution: the author and sponsor must be those of the session' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_attribution_guard BEFORE INSERT ON contribution_attribution FOR EACH ROW EXECUTE FUNCTION contribution_attribution_guard();

-- Derived from the session when its commit is recorded.
CREATE FUNCTION session_commit_attribution() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO contribution_attribution (work_session_id, project_id, repository_id, real_sha, view_sha, author_principal_id,
                                        author_executor_type, author_executor_provider, author_executor_model, author_executor_external_id, author_executor_display_name,
                                        sponsor_id, declared_author)
  SELECT s.id, s.project_id, s.repository_id, NEW.real_sha, NEW.view_sha, s.requested_by_principal_id,
         s.executor_type, s.executor_provider, s.executor_model, s.executor_external_id, s.executor_display_name,
         s.sponsor_id, NEW.declared_author
    FROM work_session s
   WHERE s.id = NEW.work_session_id AND s.session_type = 'automated_work_session' AND s.requested_by_principal_id IS NOT NULL
  ON CONFLICT (work_session_id, real_sha) DO NOTHING;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_session_commit_attribution AFTER INSERT ON session_commit FOR EACH ROW EXECUTE FUNCTION session_commit_attribution();

CREATE TRIGGER trg_attribution_immutable BEFORE UPDATE OR DELETE ON contribution_attribution FOR EACH ROW EXECUTE FUNCTION session_record_immutable();

-- Commits recorded before this migration.
INSERT INTO contribution_attribution (work_session_id, project_id, repository_id, real_sha, view_sha, author_principal_id,
                                      author_executor_type, author_executor_provider, author_executor_model, author_executor_external_id, author_executor_display_name,
                                      sponsor_id, declared_author, created_at)
SELECT s.id, s.project_id, s.repository_id, c.real_sha, c.view_sha, s.requested_by_principal_id,
       s.executor_type, s.executor_provider, s.executor_model, s.executor_external_id, s.executor_display_name, s.sponsor_id, c.declared_author, c.created_at
  FROM session_commit c JOIN work_session s ON s.id = c.work_session_id
 WHERE s.session_type = 'automated_work_session' AND s.requested_by_principal_id IS NOT NULL
ON CONFLICT (work_session_id, real_sha) DO NOTHING;

$mig$;
    INSERT INTO schema_migrations (version) VALUES ('016_contribution_attribution.sql');
    RAISE NOTICE 'applied 016_contribution_attribution.sql';
  ELSE
    RAISE NOTICE 'skipped 016_contribution_attribution.sql (already applied)';
  END IF;
END
$apply14$;

-- ---------------------------------------------------------------------------
-- 017_attestation.sql  (skipped if it is already recorded in schema_migrations)
-- ---------------------------------------------------------------------------
DO $apply15$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '017_attestation.sql') THEN
    EXECUTE $mig$
-- ---------------------------------------------------------------------------------------------------------
-- Phase 7b: attestation by an external signing authority (docs/integration/PHASE7_DESIGN.md).
--
--   attestation_authority  a public key the owner has chosen to trust as a signer ("this authority may attest to my sessions' commits")
--   attestation            a detached signature by such an authority over a canonical statement about one commit of a session
--
-- No "verified" column (a stored attestation has always been verified): the signature is checked BEFORE the row is written, and the row is never
-- changed. The database cannot verify signatures; it refuses everything else (an authority of another owner, a revoked one, a commit the session
-- did not produce, a time before the commit existed).
-- ---------------------------------------------------------------------------------------------------------

CREATE TABLE attestation_authority (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id UUID NOT NULL REFERENCES creator (id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  algorithm TEXT NOT NULL CHECK (algorithm IN ('Ed25519', 'ES256')),
  public_key_jwk JSONB NOT NULL,
  fingerprint CHAR(64) NOT NULL CHECK (fingerprint ~ '^[0-9a-f]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  CONSTRAINT uq_attestation_authority_name UNIQUE (creator_id, name),
  CONSTRAINT uq_attestation_authority_key UNIQUE (creator_id, fingerprint)
);

-- A registered authority never changes, and a revocation cannot be undone (as for principal keys).
CREATE FUNCTION attestation_authority_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'attestation_authority %: cannot be deleted, only revoked', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id <> OLD.id OR NEW.creator_id <> OLD.creator_id OR NEW.name <> OLD.name OR NEW.algorithm <> OLD.algorithm
     OR NEW.public_key_jwk IS DISTINCT FROM OLD.public_key_jwk OR NEW.fingerprint <> OLD.fingerprint OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'attestation_authority %: only revocation can change', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'attestation_authority %: a revocation cannot be undone', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_attestation_authority_guard BEFORE UPDATE OR DELETE ON attestation_authority FOR EACH ROW EXECUTE FUNCTION attestation_authority_guard();

CREATE TABLE attestation (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  work_session_id UUID NOT NULL REFERENCES work_session (id) ON DELETE CASCADE,
  authority_id UUID NOT NULL REFERENCES attestation_authority (id),
  claim TEXT NOT NULL CHECK (claim ~ '^[a-z][a-z0-9_.-]{0,63}$'),
  subject_commit CHAR(40) NOT NULL CHECK (subject_commit ~ '^[0-9a-f]{40}$'),
  payload_sha256 CHAR(64) NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  raw_payload JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(raw_payload) = 'object'),
  issued_at TIMESTAMPTZ NOT NULL,
  signature_algorithm TEXT NOT NULL CHECK (signature_algorithm IN ('Ed25519', 'ES256')),
  signature_value TEXT NOT NULL CHECK (signature_value ~ '^[A-Za-z0-9_-]{86}$'),
  submitted_by_creator_id UUID NOT NULL REFERENCES creator (id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_attestation_once UNIQUE (work_session_id, authority_id, claim, subject_commit, issued_at, payload_sha256)
);
CREATE INDEX idx_attestation_session ON attestation (work_session_id, subject_commit);

CREATE FUNCTION attestation_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  committed timestamptz;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM attestation_authority a JOIN work_session s ON s.id = NEW.work_session_id JOIN project p ON p.id = s.project_id
     WHERE a.id = NEW.authority_id AND a.creator_id = p.creator_id AND a.revoked_at IS NULL AND a.algorithm = NEW.signature_algorithm
       AND s.session_type = 'automated_work_session' AND p.creator_id = NEW.submitted_by_creator_id
  ) THEN
    RAISE EXCEPTION 'attestation: the authority must be an unrevoked authority of the session''s owner' USING ERRCODE = 'check_violation';
  END IF;
  SELECT created_at INTO committed FROM session_commit WHERE work_session_id = NEW.work_session_id AND real_sha = NEW.subject_commit;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'attestation: the commit is not one this session produced' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.issued_at < date_trunc('second', committed) THEN
    RAISE EXCEPTION 'attestation: cannot be issued before the commit existed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_attestation_guard BEFORE INSERT ON attestation FOR EACH ROW EXECUTE FUNCTION attestation_guard();
CREATE TRIGGER trg_attestation_immutable BEFORE UPDATE OR DELETE ON attestation FOR EACH ROW EXECUTE FUNCTION session_record_immutable();

$mig$;
    INSERT INTO schema_migrations (version) VALUES ('017_attestation.sql');
    RAISE NOTICE 'applied 017_attestation.sql';
  ELSE
    RAISE NOTICE 'skipped 017_attestation.sql (already applied)';
  END IF;
END
$apply15$;

-- ---------------------------------------------------------------------------
-- 018_promotion.sql  (skipped if it is already recorded in schema_migrations)
-- ---------------------------------------------------------------------------
DO $apply16$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '018_promotion.sql') THEN
    EXECUTE $mig$
-- ---------------------------------------------------------------------------------------------------------
-- Phase 8: evidence-gated promotion (docs/integration/PHASE8_DESIGN.md).
--
-- Promotion is moving a repository's default branch forward to a commit a session produced. It is asked for (by a principal holding
-- repositories:promote, or by the owner), checked against the evidence, APPROVED BY THE OWNER ONLY, and then carried out by the gateway.
--
--   pending -> approved -> completed          (approved -> failed if carrying it out fails; a failed one is final, ask again)
--   pending -> rejected
--
-- The database refuses a request that is not backed by evidence that was ready, a commit the session did not produce, an approval by anyone but
-- the session's sponsor, and any change to a request after it is made.
-- ---------------------------------------------------------------------------------------------------------

CREATE TABLE promotion_request (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  work_session_id UUID NOT NULL REFERENCES work_session (id) ON DELETE CASCADE,
  project_id UUID NOT NULL REFERENCES project (id),
  repository_id UUID NOT NULL REFERENCES repository (id),
  target_branch TEXT NOT NULL CHECK (char_length(target_branch) BETWEEN 1 AND 250),
  commit_hash CHAR(40) NOT NULL CHECK (commit_hash ~ '^[0-9a-f]{40}$'),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'completed', 'rejected', 'failed')),
  requested_by_principal_id UUID REFERENCES service_principal (id),
  requested_by_creator_id UUID REFERENCES creator (id),
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  evidence_at_request JSONB NOT NULL,
  attestations_at_request JSONB NOT NULL DEFAULT '[]'::jsonb,
  approved_by TEXT,
  approved_at TIMESTAMPTZ,
  rejected_reason TEXT,
  decided_at TIMESTAMPTZ,
  previous_tip CHAR(40) CHECK (previous_tip IS NULL OR previous_tip ~ '^[0-9a-f]{40}$'),
  evaluation_at_completion JSONB,
  completed_at TIMESTAMPTZ,
  failure_code TEXT,
  CONSTRAINT chk_promotion_one_requester CHECK ((requested_by_principal_id IS NOT NULL) <> (requested_by_creator_id IS NOT NULL)),
  CONSTRAINT chk_promotion_evidence_ready CHECK ((evidence_at_request ->> 'ready') = 'true')
);
-- One live request per commit and branch; a rejected or failed one can be asked for again.
CREATE UNIQUE INDEX uq_promotion_live ON promotion_request (work_session_id, target_branch, commit_hash) WHERE status IN ('pending', 'approved', 'completed');
CREATE INDEX idx_promotion_project ON promotion_request (project_id, status);

CREATE FUNCTION promotion_request_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  s work_session%ROWTYPE;
  ok boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO s FROM work_session WHERE id = NEW.work_session_id;
    IF NOT FOUND OR s.session_type <> 'automated_work_session' OR s.status NOT IN ('active', 'awaiting_evidence')
       OR s.project_id <> NEW.project_id OR s.repository_id <> NEW.repository_id THEN
      RAISE EXCEPTION 'promotion_request: only for a running automated session, its own project and repository' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'pending' OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.completed_at IS NOT NULL THEN
      RAISE EXCEPTION 'promotion_request: must be created pending' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM session_commit c WHERE c.work_session_id = NEW.work_session_id AND c.real_sha = NEW.commit_hash) THEN
      RAISE EXCEPTION 'promotion_request: the commit is not one this session produced' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.requested_by_principal_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM service_principal sp JOIN project p ON p.id = NEW.project_id
       WHERE sp.id = NEW.requested_by_principal_id AND sp.creator_id = p.creator_id AND 'repositories:promote' = ANY (sp.allowed_scopes)
    ) THEN
      RAISE EXCEPTION 'promotion_request: the requesting principal must hold repositories:promote for this owner' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.requested_by_creator_id IS NOT NULL AND NEW.requested_by_creator_id <> s.sponsor_id THEN
      RAISE EXCEPTION 'promotion_request: only the sponsoring owner can ask for it as a person' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'promotion_request %: cannot be deleted', OLD.id USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.id <> OLD.id OR NEW.work_session_id <> OLD.work_session_id OR NEW.project_id <> OLD.project_id OR NEW.repository_id <> OLD.repository_id
     OR NEW.target_branch <> OLD.target_branch OR NEW.commit_hash <> OLD.commit_hash
     OR NEW.requested_by_principal_id IS DISTINCT FROM OLD.requested_by_principal_id OR NEW.requested_by_creator_id IS DISTINCT FROM OLD.requested_by_creator_id
     OR NEW.requested_at <> OLD.requested_at OR NEW.evidence_at_request IS DISTINCT FROM OLD.evidence_at_request
     OR NEW.attestations_at_request IS DISTINCT FROM OLD.attestations_at_request THEN
    RAISE EXCEPTION 'promotion_request %: what was asked for cannot be changed', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NOT NULL AND (NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.approved_by IS DISTINCT FROM OLD.approved_by) THEN
    RAISE EXCEPTION 'promotion_request %: the approval cannot be changed', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  ok := CASE OLD.status
    WHEN 'pending'  THEN NEW.status IN ('approved', 'rejected')
    WHEN 'approved' THEN NEW.status IN ('completed', 'failed')
    ELSE false
  END;
  IF NOT ok THEN
    RAISE EXCEPTION 'promotion_request %: cannot go from % to %', OLD.id, OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'approved' THEN
    -- Only the sponsoring owner approves. A principal never does (there is no approval policy yet).
    SELECT * INTO s FROM work_session WHERE id = NEW.work_session_id;
    IF NEW.approved_by IS DISTINCT FROM 'creator:' || s.sponsor_id::text OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'promotion_request %: only the sponsoring owner can approve', OLD.id USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.status = 'completed' AND (NEW.completed_at IS NULL OR NEW.previous_tip IS NULL OR NEW.evaluation_at_completion IS NULL
                                   OR (NEW.evaluation_at_completion ->> 'ready') IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'promotion_request %: completion needs the time, the previous tip and evidence that was still ready', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_promotion_request_guard BEFORE INSERT OR UPDATE OR DELETE ON promotion_request FOR EACH ROW EXECUTE FUNCTION promotion_request_guard();

$mig$;
    INSERT INTO schema_migrations (version) VALUES ('018_promotion.sql');
    RAISE NOTICE 'applied 018_promotion.sql';
  ELSE
    RAISE NOTICE 'skipped 018_promotion.sql (already applied)';
  END IF;
END
$apply16$;

-- ---------------------------------------------------------------------------
-- 019_webhooks.sql  (skipped if it is already recorded in schema_migrations)
-- ---------------------------------------------------------------------------
DO $apply17$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '019_webhooks.sql') THEN
    EXECUTE $mig$
-- ---------------------------------------------------------------------------------------------------------
-- Phase 9: signed outbound webhooks (docs/integration/PHASE9_DESIGN.md).
--
--   webhook_endpoint  an https address the owner wants told about events of their projects; its signing secret is stored ENCRYPTED (never a hash:
--                     a hash cannot sign anything)
--   webhook_delivery  one row per (endpoint, event), created by a trigger in the same transaction as the event (nothing can be recorded without
--                     being owed, nothing is lost if the server is down); it only ever moves forward: pending -> delivered | dead
--   webhook_attempt   one immutable row per try, for the record
-- ---------------------------------------------------------------------------------------------------------

-- A subscription is "*", an exact event name ("promotion.completed"), or a family ("promotion.*").
CREATE FUNCTION webhook_events_valid(p text[]) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT cardinality(p) BETWEEN 1 AND 20
     AND NOT EXISTS (SELECT 1 FROM unnest(p) e WHERE e IS NULL OR e !~ '^(\*|[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*(\.\*)?)$' OR char_length(e) > 100)
$$;

CREATE FUNCTION webhook_event_matches(p text[], action text) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM unnest(p) e
     WHERE e = '*' OR e = action OR (right(e, 2) = '.*' AND starts_with(action, left(e, char_length(e) - 1)))
  )
$$;

CREATE TABLE webhook_endpoint (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  creator_id UUID NOT NULL REFERENCES creator (id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
  url TEXT NOT NULL CHECK (url ~ '^https://[^/?#@[:space:]]+' AND char_length(url) <= 2000),
  secret_ciphertext TEXT NOT NULL CHECK (secret_ciphertext ~ '^v1\.'),
  subscribed_events TEXT[] NOT NULL CHECK (webhook_events_valid(subscribed_events)),
  project_ids UUID[],                       -- NULL: every project of this owner
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  secret_rotated_at TIMESTAMPTZ,
  disabled_at TIMESTAMPTZ,
  CONSTRAINT uq_webhook_endpoint_name UNIQUE (creator_id, name),
  CONSTRAINT chk_webhook_disabled CHECK ((status = 'disabled') = (disabled_at IS NOT NULL))
);

CREATE FUNCTION webhook_endpoint_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'webhook_endpoint %: cannot be deleted, only disabled', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id <> OLD.id OR NEW.creator_id <> OLD.creator_id OR NEW.created_at <> OLD.created_at OR NEW.name <> OLD.name
     OR NEW.url <> OLD.url OR NEW.subscribed_events <> OLD.subscribed_events OR NEW.project_ids IS DISTINCT FROM OLD.project_ids THEN
    RAISE EXCEPTION 'webhook_endpoint %: only the secret and the enabled state can change (make a new endpoint to change where or what)', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_webhook_endpoint_guard BEFORE UPDATE OR DELETE ON webhook_endpoint FOR EACH ROW EXECUTE FUNCTION webhook_endpoint_guard();

CREATE TABLE webhook_delivery (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  endpoint_id UUID NOT NULL REFERENCES webhook_endpoint (id),
  -- Deliberately not a foreign key: nothing may reference the append-only event table in a way that changes how it can be refused or truncated.
  -- The trigger below is the only thing that creates these rows, from an event that has just been written.
  event_id UUID NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'dead')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 20),
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  payload_sha256 CHAR(64) CHECK (payload_sha256 IS NULL OR payload_sha256 ~ '^[0-9a-f]{64}$'),
  last_status INTEGER,
  last_error TEXT CHECK (last_error IS NULL OR char_length(last_error) <= 300),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  delivered_at TIMESTAMPTZ,
  CONSTRAINT uq_webhook_delivery UNIQUE (endpoint_id, event_id),
  CONSTRAINT chk_webhook_delivered CHECK ((status = 'delivered') = (delivered_at IS NOT NULL))
);
CREATE INDEX idx_webhook_delivery_due ON webhook_delivery (next_attempt_at) WHERE status = 'pending';
CREATE INDEX idx_webhook_delivery_endpoint ON webhook_delivery (endpoint_id, created_at DESC);

-- Bookkeeping only: what is owed and to whom never changes, a finished delivery is final, the attempt count goes up by one at a time,
-- and the body that was signed is the same every time.
CREATE FUNCTION webhook_delivery_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'webhook_delivery %: cannot be deleted', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.id <> OLD.id OR NEW.endpoint_id <> OLD.endpoint_id OR NEW.event_id <> OLD.event_id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'webhook_delivery %: what is owed, and to whom, cannot change', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'webhook_delivery %: a finished delivery is final', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.attempts < OLD.attempts OR NEW.attempts > OLD.attempts + 1 THEN
    RAISE EXCEPTION 'webhook_delivery %: attempts go up one at a time', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.payload_sha256 IS NOT NULL AND NEW.payload_sha256 IS DISTINCT FROM OLD.payload_sha256 THEN
    RAISE EXCEPTION 'webhook_delivery %: the signed body cannot change between attempts', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_webhook_delivery_guard BEFORE UPDATE OR DELETE ON webhook_delivery FOR EACH ROW EXECUTE FUNCTION webhook_delivery_guard();

CREATE TABLE webhook_attempt (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  delivery_id UUID NOT NULL REFERENCES webhook_delivery (id),
  attempt INTEGER NOT NULL CHECK (attempt >= 1),
  started_at TIMESTAMPTZ NOT NULL,
  duration_ms INTEGER NOT NULL CHECK (duration_ms >= 0),
  outcome TEXT NOT NULL CHECK (outcome IN ('delivered', 'http_error', 'network_error', 'timeout', 'blocked_address', 'endpoint_unavailable')),
  http_status INTEGER,
  error TEXT CHECK (error IS NULL OR char_length(error) <= 300),
  CONSTRAINT uq_webhook_attempt UNIQUE (delivery_id, attempt)
);
CREATE TRIGGER trg_webhook_attempt_immutable BEFORE UPDATE OR DELETE ON webhook_attempt FOR EACH ROW EXECUTE FUNCTION session_record_immutable();

-- Fan-out: when an event is written, every active endpoint of the project's owner that subscribed to it is owed a delivery, in the same transaction.
CREATE FUNCTION webhook_fan_out() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  INSERT INTO webhook_delivery (endpoint_id, event_id)
  SELECT e.id, NEW.id
    FROM webhook_endpoint e JOIN project p ON p.id = NEW.project_id
   WHERE e.status = 'active' AND e.creator_id = p.creator_id
     AND (e.project_ids IS NULL OR NEW.project_id = ANY (e.project_ids))
     AND webhook_event_matches(e.subscribed_events, NEW.action)
  ON CONFLICT (endpoint_id, event_id) DO NOTHING;
  RETURN NEW;
END
$$;
REVOKE ALL ON FUNCTION webhook_fan_out() FROM PUBLIC;
CREATE TRIGGER trg_event_webhook_fan_out AFTER INSERT ON event FOR EACH ROW EXECUTE FUNCTION webhook_fan_out();

$mig$;
    INSERT INTO schema_migrations (version) VALUES ('019_webhooks.sql');
    RAISE NOTICE 'applied 019_webhooks.sql';
  ELSE
    RAISE NOTICE 'skipped 019_webhooks.sql (already applied)';
  END IF;
END
$apply17$;

-- ---------------------------------------------------------------------------
-- server/roles.sql  (the custody_app grants; safe to repeat)
-- ---------------------------------------------------------------------------
-- Custody Core Restricted Database Role: custody_app
-- This role has least-privilege permissions:
-- 1. Only SELECT and INSERT on the 'event' table (no UPDATE, no DELETE, no TRUNCATE, no trigger modification/ownership).
-- 2. SELECT, INSERT, UPDATE on other domain tables.
-- 3. The application runtime must connect using this role, never as the 'postgres' superuser.

DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'custody_app') THEN
    -- No password here: this file is public. The server sets it from APP_DB_PASSWORD after running this file;
    -- until then nobody can sign in as custody_app.
    CREATE ROLE custody_app WITH LOGIN;
  END IF;
END
$$;

-- Grant schema access
GRANT USAGE ON SCHEMA public TO custody_app;

-- Grant base table permissions
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO custody_app;

-- Strictly revoke mutation privileges on event table
-- Events are written only through append_event(), which assigns seq, prev_hash, timestamp and hash.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE event FROM custody_app;
GRANT EXECUTE ON FUNCTION append_event(uuid, text, text, text, text, text, jsonb) TO custody_app;

-- Second factor (migration 005): attempts are a record, so the app may add and read them but never change them.
-- Account events, like project events, are written only through append_account_event().
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE mfa_attempt FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE mfa_session FROM custody_app;
REVOKE DELETE, TRUNCATE ON TABLE mfa_factor FROM custody_app;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE account_event FROM custody_app;
-- Only the operator clears a reset requirement.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE mfa_legacy_reset FROM custody_app;
GRANT EXECUTE ON FUNCTION append_account_event(text, text, text, text, jsonb) TO custody_app;

-- Service principals (migration 010). The app has no DELETE anywhere, so expired client assertions are removed
-- by one narrow SECURITY DEFINER function.
GRANT EXECUTE ON FUNCTION purge_expired_client_assertions() TO custody_app;

-- Work sessions (migration 012): the trigger that mirrors a door into its session runs as the application account and
-- calls this one function.
GRANT EXECUTE ON FUNCTION work_session_status_for_door(text, text) TO custody_app;

-- Session materialization (migration 014): what was provisioned and which real commit each pushed commit became are records.
-- The application may add them and read them, never change or delete them (a trigger refuses it too).
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE session_view FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE session_commit FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE evidence_requirement FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE evidence_submission FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE contribution_attribution FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE attestation FROM custody_app;
REVOKE DELETE, TRUNCATE ON TABLE attestation_authority FROM custody_app;
REVOKE DELETE, TRUNCATE ON TABLE promotion_request FROM custody_app;
REVOKE DELETE, TRUNCATE ON TABLE webhook_endpoint FROM custody_app;
REVOKE DELETE, TRUNCATE ON TABLE webhook_delivery FROM custody_app;
REVOKE UPDATE, DELETE, TRUNCATE ON TABLE webhook_attempt FROM custody_app;
-- Used by a CHECK constraint on webhook_endpoint, which is evaluated as the application's account.
GRANT EXECUTE ON FUNCTION webhook_events_valid(text[]) TO custody_app;
GRANT EXECUTE ON FUNCTION webhook_event_matches(text[], text) TO custody_app;

-- The app role must not be able to create objects (for example look-alike functions) in this schema.
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- Grant sequence permissions for identity/auto-increment columns
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO custody_app;

-- Ensure future tables grant permissions correctly if needed
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE ON TABLES TO custody_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO custody_app;

-- The migration bookkeeping table is for the admin role only; the app must not edit it.
DO $$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL THEN
    REVOKE ALL ON TABLE schema_migrations FROM custody_app;
  END IF;
END
$$;

-- Supabase's built-in REST API is closed to all of the above by server/lockdown.sql, which runs after this file
-- (and inside every migration).


-- ---------------------------------------------------------------------------
-- server/lockdown.sql  (closes Supabase's REST API to our tables and functions; safe to repeat)
-- ---------------------------------------------------------------------------
-- ---------------------------------------------------------------------------------------------------------
-- Close Supabase's built-in REST API (Data API) to everything of ours.
--
-- On Supabase, every table and function in schema public is served at /rest/v1 to the roles anon and
-- authenticated, with the PUBLIC key that is in the browser, and new tables get full rights for those roles.
-- Custody Core never uses that API: all access goes through our server as custody_app. So those roles get
-- no access at all, and row-level security is on for every table (only custody_app has a policy; the
-- table owner and SECURITY DEFINER functions are not affected). On a plain PostgreSQL without those roles
-- the role-specific part is skipped.
--
-- It refers to no particular table or function, so it can run inside every migration's own transaction:
-- nothing a migration creates is ever committed while open. It runs again after server/roles.sql.
-- ---------------------------------------------------------------------------------------------------------

-- Functions are executable by PUBLIC (every role) unless revoked. Only custody_app needs any of ours, and
-- server/roles.sql grants it exactly those. The default-privileges line has no IN SCHEMA on purpose: a per-schema
-- default cannot take away PostgreSQL's global "PUBLIC may execute" default, so without this every function a
-- later migration creates would be callable through the REST API.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
ALTER DEFAULT PRIVILEGES REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

DO $$
DECLARE
  r text;
  t record;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON SCHEMA public FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM %I', r);
    END IF;
  END LOOP;

  FOR t IN
    SELECT c.relname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.relname);
    -- (On the very first migration custody_app does not exist yet; roles.sql creates it and this runs again.)
    IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'custody_app') AND NOT EXISTS (SELECT FROM pg_catalog.pg_policies WHERE schemaname = 'public' AND tablename = t.relname AND policyname = 'custody_app_access') THEN
      EXECUTE format('CREATE POLICY custody_app_access ON public.%I FOR ALL TO custody_app USING (true) WITH CHECK (true)', t.relname);
    END IF;
  END LOOP;
END
$$;


COMMIT;
